  {
    "question": "According to the DBMS Course Syllabus, what portion of the overall course assessment is allocated to the \"DBMS Foundations\" module?",
    "options": {
      "A": "6 %",
      "B": "12 %",
      "C": "15 %",
      "D": "20 %"
    },
    "correct_answer": "A",
    "explanation": "The syllabus explicitly lists \"DBMS Foundations – 6%\" under the assessment breakdown, indicating that this module contributes 6 % to the final grade.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following subjects are listed as prerequisites for enrolling in CSE‑DBMS‑301?",
    "options": {
      "A": "Data structures and operating systems",
      "B": "Programming fundamentals and discrete mathematics",
      "C": "Computer networks and algorithms",
      "D": "Software engineering and linear algebra"
    },
    "correct_answer": "B",
    "explanation": "The syllabus states the prerequisites are \"Programming fundamentals and discrete mathematics,\" making option B the correct choice.",
    "difficulty": "Medium"
  },
  {
    "question": "In the DBMS architecture described in the syllabus, which component is primarily responsible for converting a user’s SQL statement into an execution plan?",
    "options": {
      "A": "Storage manager",
      "B": "Transaction manager",
      "C": "Query processor",
      "D": "Authorization manager"
    },
    "correct_answer": "C",
    "explanation": "The query processor parses, validates, and optimizes SQL statements, producing an execution plan for the storage manager to carry out.",
    "difficulty": "Medium"
  },
  {
    "question": "How many lecture hours are scheduled for the DBMS course according to the syllabus?",
    "options": {
      "A": "24 lecture hours",
      "B": "30 lecture hours",
      "C": "36 lecture hours",
      "D": "42 lecture hours"
    },
    "correct_answer": "C",
    "explanation": "The syllabus lists \"36 lecture hours + 24 laboratory hours\" for the 12‑week course, so the lecture component is 36 hours.",
    "difficulty": "Medium"
  },
  {
    "question": "What is the main educational purpose of the \"UniversityDB\" example mentioned in the syllabus?",
    "options": {
      "A": "To illustrate low‑level file system operations",
      "B": "To provide a concrete, application‑driven scenario for designing and implementing a database",
      "C": "To demonstrate advanced machine‑learning integration with DBMS",
      "D": "To compare relational and NoSQL data models"
    },
    "correct_answer": "B",
    "explanation": "The syllabus describes the course as \"application‑driven\" and states that students progressively design and implement UniversityDB, making option B the correct description of its purpose.",
    "difficulty": "Medium"
  }
]
